// Finite changes of the authored operation, not a first derivative. Small
// log/exponential changes retain sub-ULP offsets; boundary paths keep clamps.
export const nonlinearDifferentialGLSL=`
float hbRayDeltaLogOnePlus(float x){if(abs(x)>=.125)return log(1.0+x);float t=x/(2.0+x),s=t*t;return 2.0*t*(1.0+s*(.3333333333333333+s*(.2+s*(.14285714285714285+s*.1111111111111111))));}
float hbRayDeltaExpMinusOne(float x){if(abs(x)>=.125)return exp(x)-1.0;return x*(1.0+x*(.5+x*(.16666666666666666+x*(.041666666666666664+x*(.008333333333333333+x*.001388888888888889)))));}
vec4 hbRayDeltaExp(vec4 a,vec4 da){vec4 result;for(int hbLane=0;hbLane<4;hbLane++)result[hbLane]=exp2(a[hbLane])*hbRayDeltaExpMinusOne(da[hbLane]*.6931471805599453);return result;}
vec4 hbRayDeltaLog(vec4 a,vec4 da){vec4 z=vec4(.000001,.000001,.000001,.000001),d=hbRayDeltaMax(a,z,da,vec4(0,0,0,0)),result;for(int hbLane=0;hbLane<4;hbLane++){float old=max(a[hbLane],.000001);result[hbLane]=abs(d[hbLane])<=old*.125?hbRayDeltaLogOnePlus(d[hbLane]/old)*1.4426950408889634:log2(max(a[hbLane]+da[hbLane],.000001))-log2(old);}return result;}
vec4 hbRayDeltaPower(vec4 a,vec4 b,vec4 da,vec4 db){vec4 z=vec4(0,0,0,0),change=hbRayDeltaMax(a,z,da,z),result;for(int hbLane=0;hbLane<4;hbLane++){float old=max(a[hbLane],0.0),next=max(a[hbLane]+da[hbLane],0.0);if(old>0.0&&next>0.0){float dl=abs(change[hbLane])<=old*.125?hbRayDeltaLogOnePlus(change[hbLane]/old):log(next)-log(old),exponent=b[hbLane]*dl+db[hbLane]*log(old)+db[hbLane]*dl;result[hbLane]=abs(exponent)<.125?pow(old,b[hbLane])*hbRayDeltaExpMinusOne(exponent):pow(next,b[hbLane]+db[hbLane])-pow(old,b[hbLane]);}else result[hbLane]=pow(next,b[hbLane]+db[hbLane])-pow(old,b[hbLane]);}return result;}
vec4 hbRayDeltaSmooth(vec4 a,vec4 b,vec4 c,vec4 da,vec4 db,vec4 dc){vec4 z=vec4(0,0,0,0),one=vec4(1,1,1,1),eps=vec4(.000001,.000001,.000001,.000001),den=max(b-a,eps),dden=hbRayDeltaMax(b-a,eps,db-da,z),q=(c-a)/den,dq=hbRayDeltaDivide(c-a,den,dc-da,dden),t=clamp(q,0.0,1.0),dt=hbRayDeltaMin(max(q,z),one,hbRayDeltaMax(q,z,dq,z),z);return dt*(6.0*t*(one-t)+dt*(vec4(3,3,3,3)-6.0*t-2.0*dt));}
vec4 hbRayDeltaNormalMap(vec4 a,vec4 b,vec4 da,vec4 db){vec3 n=vec3((a.xy*2.0-1.0)*b.x,a.z*2.0-1.0),dn=vec3(2.0*da.xy*b.x+(a.xy*2.0-1.0)*db.x+2.0*da.xy*db.x,2.0*da.z);float old=length(n),next=length(n+dn);vec3 base=old>0.0?n/max(old,1e-20):vec3(0,0,1);if(old<=0.0||next<=0.0)return vec4((next>0.0?(n+dn)/max(next,1e-20):vec3(0,0,1))-base,0);float dl=hbRayDeltaLength(vec4(n,0),vec4(dn,0)),dden=old>=1e-20?max(dl,1e-20-old):max(old-1e-20+dl,0.0),den=max(next,1e-20);return vec4(dn/den-base*(dden/den),0);}
vec4 hbRayDeltaFresnel(vec4 a,vec4 b,vec4 c,vec4 d,vec4 da,vec4 db,vec4 dc,vec4 dd){vec4 z=vec4(0,0,0,0),one=vec4(1,1,1,1);float al=max(length(a.xyz),1e-30),bl=max(length(b.xyz),1e-30),an=max(length(a.xyz+da.xyz),1e-30),bn=max(length(b.xyz+db.xyz),1e-30);vec3 x=a.xyz/al,y=b.xyz/bl,dx=da.xyz/an-x*(hbRayDeltaLength(vec4(a.xyz,0),vec4(da.xyz,0))/an),dy=db.xyz/bn-y*(hbRayDeltaLength(vec4(b.xyz,0),vec4(db.xyz,0))/bn);float q=dot(x,y),dq=dot(x,dy)+dot(dx,y)+dot(dx,dy),clamped=clamp(q,0.0,1.0),dt=hbRayDeltaMin(max(vec4(q,q,q,q),z),one,hbRayDeltaMax(vec4(q,q,q,q),z,vec4(dq,dq,dq,dq),z),z).x,exponent=max(c.x,.0001),de=hbRayDeltaMax(c,vec4(.0001,.0001,.0001,.0001),dc,z).x,p=pow(1.0-clamped,exponent),dp=hbRayDeltaPower(vec4(1.0-clamped,1.0-clamped,1.0-clamped,1.0-clamped),vec4(exponent,exponent,exponent,exponent),vec4(-dt,-dt,-dt,-dt),vec4(de,de,de,de)).x;float result=dd.x+(1.0-d.x)*dp-dd.x*p-dd.x*dp;return vec4(result,result,result,result);}
vec4 hbRayDeltaRadial(vec4 a,vec4 b,vec4 c,vec4 da,vec4 db,vec4 dc){vec4 z=vec4(0,0,0,0),eps=vec4(.000001,.000001,.000001,.000001);float size=length(a.xy-b.xy),ds=hbRayDeltaLength(vec4(a.xy-b.xy,0,0),vec4(da.xy-db.xy,0,0)),den=max(c.x,.000001),dden=hbRayDeltaMax(c,eps,dc,z).x,q=1.0-size/den,dq=-hbRayDeltaDivide(vec4(size,size,size,size),vec4(den,den,den,den),vec4(ds,ds,ds,ds),vec4(dden,dden,dden,dden)).x;vec4 v=vec4(q,q,q,q),dv=vec4(dq,dq,dq,dq);return hbRayDeltaMin(max(v,z),vec4(1,1,1,1),hbRayDeltaMax(v,z,dv,z),z);}
vec4 hbRayDeltaLinear(vec4 a,vec4 b,vec4 da,vec4 db){vec2 p=a.xy-vec2(.5,.5),axis=vec2(cos(b.x),sin(b.x));float h=sin(db.x*.5);vec2 change=vec2(-sin(b.x)*sin(db.x)-2.0*cos(b.x)*h*h,cos(b.x)*sin(db.x)-2.0*sin(b.x)*h*h);float q=dot(p,axis)+.5,dq=dot(da.xy,axis)+dot(p,change)+dot(da.xy,change);vec4 v=vec4(q,q,q,q),dv=vec4(dq,dq,dq,dq),z=vec4(0,0,0,0);return hbRayDeltaMin(max(v,z),vec4(1,1,1,1),hbRayDeltaMax(v,z,dv,z),z);}
`;
export const nonlinearDifferentialExpressions=Object.freeze({exp2:'hbRayDeltaExp(a,aDelta)',log2:'hbRayDeltaLog(a,aDelta)',power:'hbRayDeltaPower(a,b,aDelta,bDelta)',smoothstep:'hbRayDeltaSmooth(a,b,c,aDelta,bDelta,cDelta)',normalMap:'hbRayDeltaNormalMap(a,b,aDelta,bDelta)',fresnel:'hbRayDeltaFresnel(a,b,c,d,aDelta,bDelta,cDelta,dDelta)',radialGradient:'hbRayDeltaRadial(a,b,c,aDelta,bDelta,cDelta)',linearGradient:'hbRayDeltaLinear(a,b,aDelta,bDelta)'});
export function nonlinearDifferentialNode(T,operation,base,delta,H){
 const[a,b,c,d]=base,[da,db,dc,dd]=delta,{lanes,minLane,maxLane,lengthDelta,divideLane}=H,z=T.float(0),one=T.float(1);
 const log1p=x=>{const t=x.div(x.add(2)).toVar(),s=t.mul(t).toVar();return x.abs().greaterThanEqual(.125).select(x.add(1).log(),t.mul(2).mul(s.mul(s.mul(s.mul(s.mul(1/9).add(1/7)).add(1/5)).add(1/3)).add(1)));};
 const expm1=x=>x.abs().greaterThanEqual(.125).select(x.exp().sub(1),x.mul(x.mul(x.mul(x.mul(x.mul(x.mul(1/720).add(1/120)).add(1/24)).add(1/6)).add(.5)).add(1)));
 const power=(a,b,da,db)=>{const old=a.max(0).toVar(),next=a.add(da).max(0).toVar(),change=maxLane(a,z,da,z).toVar(),dl=change.abs().lessThanEqual(old.mul(.125)).select(log1p(change.div(old)),next.log().sub(old.log())).toVar(),exponent=b.mul(dl).add(db.mul(old.log())).add(db.mul(dl)).toVar();return old.greaterThan(0).and(next.greaterThan(0)).select(exponent.abs().lessThan(.125).select(old.pow(b).mul(expm1(exponent)),next.pow(b.add(db)).sub(old.pow(b))),next.pow(b.add(db)).sub(old.pow(b)));};
 const saturate=(a,da)=>minLane(a.max(0),one,maxLane(a,z,da,z),z);
 switch(operation){
  case'exp2':return lanes(k=>a[k].exp2().mul(expm1(da[k].mul(Math.LN2))));
  case'log2':return lanes(k=>{const old=a[k].max(1e-6).toVar(),change=maxLane(a[k],T.float(1e-6),da[k],z).toVar();return change.abs().lessThanEqual(old.mul(.125)).select(log1p(change.div(old)).mul(Math.LOG2E),a[k].add(da[k]).max(1e-6).log2().sub(old.log2()));});
  case'power':return lanes(k=>power(a[k],b[k],da[k],db[k]));
  case'smoothstep':return lanes(k=>{const den=b[k].sub(a[k]).max(1e-6).toVar(),dden=maxLane(b[k].sub(a[k]),T.float(1e-6),db[k].sub(da[k]),z).toVar(),q=c[k].sub(a[k]).div(den).toVar(),dq=divideLane(c[k].sub(a[k]),den,dc[k].sub(da[k]),dden).toVar(),t=q.clamp(0,1).toVar(),dt=saturate(q,dq).toVar();return dt.mul(t.mul(6).mul(one.sub(t)).add(dt.mul(T.float(3).sub(t.mul(6)).sub(dt.mul(2)))));});
  case'normalMap':{const n=T.vec3(a.xy.mul(2).sub(1).mul(b.x),a.z.mul(2).sub(1)).toVar(),dn=T.vec3(da.xy.mul(2).mul(b.x).add(a.xy.mul(2).sub(1).mul(db.x)).add(da.xy.mul(2).mul(db.x)),da.z.mul(2)).toVar(),old=n.length().toVar(),next=n.add(dn).length().toVar(),base=old.greaterThan(0).select(n.div(old.max(1e-20)),T.vec3(0,0,1)).toVar(),dl=lengthDelta(T.vec4(n,0),T.vec4(dn,0)).toVar(),dden=maxLane(old,T.float(1e-20),dl,z).toVar(),den=next.max(1e-20),value=dn.div(den).sub(base.mul(dden.div(den))),boundary=next.greaterThan(0).select(n.add(dn).div(den),T.vec3(0,0,1)).sub(base);return T.vec4(old.greaterThan(0).and(next.greaterThan(0)).select(value,boundary),0);}
  case'fresnel':{const al=a.xyz.length().max(1e-30),bl=b.xyz.length().max(1e-30),an=a.xyz.add(da.xyz).length().max(1e-30),bn=b.xyz.add(db.xyz).length().max(1e-30),x=a.xyz.div(al).toVar(),y=b.xyz.div(bl).toVar(),dx=da.xyz.div(an).sub(x.mul(lengthDelta(T.vec4(a.xyz,0),T.vec4(da.xyz,0)).div(an))).toVar(),dy=db.xyz.div(bn).sub(y.mul(lengthDelta(T.vec4(b.xyz,0),T.vec4(db.xyz,0)).div(bn))).toVar(),q=x.dot(y).toVar(),dq=x.dot(dy).add(dx.dot(y)).add(dx.dot(dy)).toVar(),dt=saturate(q,dq).toVar(),exponent=c.x.max(.0001).toVar(),de=maxLane(c.x,T.float(.0001),dc.x,z).toVar(),p=one.sub(q.clamp(0,1)).pow(exponent).toVar(),dp=power(one.sub(q.clamp(0,1)),exponent,dt.negate(),de).toVar();return T.vec4(dd.x.add(one.sub(d.x).mul(dp)).sub(dd.x.mul(p)).sub(dd.x.mul(dp)));}
  case'radialGradient':{const size=a.xy.sub(b.xy).length().toVar(),ds=lengthDelta(T.vec4(a.xy.sub(b.xy),0,0),T.vec4(da.xy.sub(db.xy),0,0)).toVar(),den=c.x.max(1e-6).toVar(),dden=maxLane(c.x,T.float(1e-6),dc.x,z).toVar(),q=one.sub(size.div(den)).toVar(),dq=divideLane(size,den,ds,dden).negate().toVar();return T.vec4(saturate(q,dq));}
  case'linearGradient':{const p=a.xy.sub(.5),axis=T.vec2(b.x.cos(),b.x.sin()),h=db.x.mul(.5).sin(),change=T.vec2(b.x.sin().negate().mul(db.x.sin()).sub(b.x.cos().mul(2).mul(h).mul(h)),b.x.cos().mul(db.x.sin()).sub(b.x.sin().mul(2).mul(h).mul(h))).toVar(),q=p.dot(axis).add(.5).toVar(),dq=da.xy.dot(axis).add(p.dot(change)).add(da.xy.dot(change)).toVar();return T.vec4(saturate(q,dq));}
  default:return null;
 }
}
